# name: target_in_set_yes_rate
# description: Proportion of "yes" when the target is one of the shown examples; observed below the model's null means the model over-predicts endorsement of already-seen examples (humans lapse/hedge even on members), above means it under-predicts it.
def test_statistic(df):
    s = df["number_set"].astype(str)
    t = df["target"].astype(int).astype(str)
    padded = "," + s + ","
    inset = np.array([p.find("," + x + ",") >= 0 for p, x in zip(padded.values, t.values)])
    if inset.sum() == 0:
        return 0.0
    return float(df["rating"].values[inset].mean())

# name: between_set_yes_rate_sd
# description: Standard deviation, across example sets with at least 20 responses, of the per-set yes-rate; observed above the null means the model makes sets too similar in overall generality (under-produces set-to-set differences in concept breadth), below means it exaggerates them.
def test_statistic(df):
    g = df.groupby(df["number_set"].astype(str))["rating"].agg(["mean", "count"])
    g = g[g["count"] >= 20]
    if len(g) < 2:
        return 0.0
    return float(g["mean"].std())

# name: far_target_yes_rate
# description: Proportion of "yes" for targets more than 40 away from every example; observed above the model's null means the model under-produces broad/random endorsement of distant targets (e.g. missing lapse or very broad concepts), below means it over-produces it.
def test_statistic(df):
    arr = df["number_set"].astype(str).str.split(",", expand=True).apply(pd.to_numeric, errors="coerce").values.astype(float)
    t = df["target"].astype(float).values[:, None]
    dist = np.nanmin(np.abs(arr - t), axis=1)
    m = dist > 40
    if m.sum() == 0:
        return 0.0
    return float(df["rating"].values[m].mean())
